// 同一Common实际捕获跨recipe接批；只有原coverage成功才可采用provisional，不作历史账。
#define main private_shop_original_recipe_projection_main
#include "private_shop_freight_recipe_projection_test.cpp"
#undef main
#include "resident/domains/commerce/freight/private_shop_freight_capture_projection.hpp"
#include "resident/storage/resource_execution_coverage.hpp"
namespace {
// 真实拆批、原reservation转运及后续消费分三次recipe，旧同品新建不接替来源。
void actual_sequence(){
 Fixture f;auto boundary=capture_private_shop_freight_projection_boundary(f.common,f.selection());require(boundary.ok,"capture original selected cargo");require(f.common.apply_resources({{ReserveLots{"bag","grain",3,{f.owner},f.action}},{}}).ok,"first original split recipe");const auto split=f.common.resource_execution_drafts().back().operations.front().lot_flows.front().destination_lot_id;
 require(f.common.apply_resources({{TransferLots{"bag","destination","grain",3,{f.owner},f.action,std::nullopt}},{}}).ok,"second original transfer recipe");const auto moved=f.common.resource_execution_drafts().back().operations.front().lot_flows.front().destination_lot_id;
 require(f.common.apply_resources({{ConsumeLots{"destination","grain",2,{f.owner},{}},AddLot{"destination","grain",10,f.owner,{}}},{}}).ok,"third consume plus unrelated same-item add");auto read=read_private_shop_freight_capture_projection(f.common,boundary.value);require(read.ok,"three real recipes match prior and following frames");check(read.value.recipes.size()==3&&read.value.remaining_lots.size()==2,"all actual recipes and only real surviving descendants retained");check(read.value.remaining_lots[0].lot.id==f.original&&read.value.remaining_lots[0].lot.quantity==5&&read.value.remaining_lots[1].lot.id==moved&&read.value.remaining_lots[1].lot.quantity==1,"actual original remainder and transferred remainder, not replenishment");check(read.value.recipes[1].operations.front().original_flows.front().source_lot_id==split,"cross-recipe transfer keeps real prior split source");
 auto& drafts=const_cast<std::vector<ResourceExecutionDraft>&>(f.common.resource_execution_drafts());const auto saved=drafts;drafts[1].operations.front().inventories.front().before->capacity++;check(!read_private_shop_freight_capture_projection(f.common,boundary.value).ok,"before frame from another recipe cannot change container constraint");drafts=saved;drafts.erase(drafts.begin());check(!read_private_shop_freight_capture_projection(f.common,boundary.value).ok,"missing earlier split cannot be restored from current equal commodity");drafts=saved;
 auto* bag=f.common.state().inventories.find("bag");std::swap(bag->lots[0],bag->lots[1]);check(!read_private_shop_freight_capture_projection(f.common,boundary.value).ok,"unchanged lot values cannot hide reordered original FIFO batches");std::swap(bag->lots[0],bag->lots[1]);bag->lots.front().quantity--;check(!read_private_shop_freight_capture_projection(f.common,boundary.value).ok,"unobserved current selected lot mutation refused");bag->lots.front().quantity++;check(read_private_shop_freight_capture_projection(f.common,boundary.value).ok,"original actual frames remain readable after negative fixture restored");
}
// 完全消费后的后来同品批不继承旧身份，已经消失的选定货不能借最后数量复活。
void consume_replenish_and_lifecycle(){
 Fixture f;auto b=capture_private_shop_freight_projection_boundary(f.common,f.selection());require(b.ok,"original consumed cargo boundary");require(f.common.apply_resources({{ConsumeLots{"bag","grain",8,{f.owner},{}}},{}}).ok,"actual full consumption");require(f.common.apply_resources({{AddLot{"bag","grain",8,f.owner,{}}},{}}).ok,"later separate replenishment");auto read=read_private_shop_freight_capture_projection(f.common,b.value);check(read.ok&&read.value.recipes.size()==2&&read.value.remaining_lots.empty(),"later same-item receipt never restores consumed original");require(f.common.finish_resource_execution_capture().ok,"finish actual original cargo capture");require(f.common.begin_resource_execution_capture().ok,"reopen same Common capture");check(!read_private_shop_freight_capture_projection(f.common,b.value).ok,"old opaque boundary fails after capture restart");
 Fixture idle;auto before=capture_private_shop_freight_projection_boundary(idle.common,idle.selection());require(before.ok,"actual untouched original selection");auto unchanged=read_private_shop_freight_capture_projection(idle.common,before.value);check(unchanged.ok&&unchanged.value.recipes.empty()&&unchanged.value.remaining_lots.size()==1,"no recipe preserves actual original lot without inventing a transition");check(!capture_private_shop_freight_projection_boundary(idle.common,{{"bag",{idle.original,idle.original}}}).ok,"duplicate original selection refused");
}
// 域读不替代全表coverage；不相关资源的漏记变化也会让最后原coverage拒整个候选。
void coverage_adoption_boundary(){
 for(bool gap:{false,true}){Fixture f;require(f.common.finish_resource_execution_capture().ok,"close fixture preparation capture");auto coverage=begin_resource_execution_coverage(f.common);require(coverage.ok,"start original complete capture coverage");auto b=capture_private_shop_freight_projection_boundary(f.common,f.selection());require(b.ok,"capture selected original frames inside complete coverage");require(f.common.apply_resources({{AdjustLots{"bag",{{f.original,-1}},false}},{}}).ok,"real selected quantity operation");auto provisional=read_private_shop_freight_capture_projection(f.common,b.value);require(provisional.ok,"provisional selected projection before full coverage");if(gap)f.common.state().inventories.find("destination")->capacity--;auto finished=finish_resource_execution_coverage(f.common,coverage.value);check(finished.ok!=gap,"full original coverage independently governs result adoption");if(!gap)check(finished.value.size()==provisional.value.recipes.size(),"successful whole coverage retains exact real recipe count");check(!read_private_shop_freight_capture_projection(f.common,b.value).ok,"finished capture cannot be consumed again through old domain boundary");}
}
}
int main(){try{actual_sequence();consume_replenish_and_lifecycle();coverage_adoption_boundary();}catch(const std::exception& e){check(false,e.what());}std::cout<<"FREIGHT_CAPTURE_PROJECTION_CHECKS="<<checks<<" FAILURES="<<failures<<'\n';return failures?1:0;}
